<script setup lang="ts">import {ref,onMounted} from 'vue';import type {Audit} from '../types/domain';import {researchApi} from '../api/research';import PageTitle from '../components/common/PageTitle.vue';import Table from '../components/common/Table.vue';import Notice from '../components/common/Notice.vue';import {date} from '../utils/format';const rows=ref<Audit[]>([]),error=ref('');async function reload(){try{rows.value=await researchApi.audit()}catch(e){error.value=e.message}}onMounted(reload)</script><template><PageTitle index="06 / PROOF TRACE" title="每次校对，都留一份底稿。" description="登录、快照导入、比较入队/完成、补采计划与审稿均保留操作者和时间，最近200条倒排。"><button @click="reload">刷新底稿 ↻</button></PageTitle><Notice :error="error"/><Table :headers="['时间','操作者','动作','细节']"><tr v-for="a in rows" :key="a.id"><td class="mono">{{date(a.created_at)}}</td><td>{{a.actor}}</td><td><strong>{{a.action}}</strong></td><td class="detail">{{JSON.stringify(a.detail)}}</td></tr></Table></template>
